import {createInterface} from 'node:readline';import {writeFileSync,appendFileSync,readFileSync,existsSync} from 'node:fs';import {join} from 'node:path';
const arg=process.argv.indexOf('--session');const file=arg>=0?process.argv[arg+1]:join(process.env.VIEW_FIXTURE_DIR,`session-${process.pid}.jsonl`);let seq=0,running=false,executions=0;const prompts=[];const messages=[];let current;const header={type:'session',version:3,id:`fixture-${process.pid}`,cwd:process.cwd(),timestamp:new Date().toISOString()};if(!existsSync(file))writeFileSync(file,JSON.stringify(header)+'\n');
const emit=record=>process.stdout.write(JSON.stringify(record)+'\n');const response=(command,data)=>emit({type:'response',id:command.id,command:command.type,success:true,...(data===undefined?{}:{data})});const entry=message=>{const id=`entry-${process.pid}-${++seq}`;appendFileSync(file,JSON.stringify({type:'message',id,parentId:seq>1?`entry-${process.pid}-${seq-1}`:null,timestamp:new Date().toISOString(),message})+'\n');messages.push(message);};
const assistant=text=>({role:'assistant',content:[{type:'text',text}],api:'faux',provider:'fixture',model:'fixture',stopReason:'toolUse',timestamp:Date.now(),usage:{input:0,output:0,cacheRead:0,cacheWrite:0,totalTokens:0,cost:{input:0,output:0,cacheRead:0,cacheWrite:0,total:0}}});
function settle(){if(!running)return;running=false;emit({type:'tool_execution_end',toolCallId:'gate',toolName:'view_test_gate',result:{content:[{type:'text',text:'gate complete'}]},isError:false});const done={...assistant('earlier UTF8 界👋 partial complete'),stopReason:'stop'};entry(done);emit({type:'message_end',message:done});emit({type:'agent_end',messages:[done]});emit({type:'agent_settled'});}
createInterface({input:process.stdin,terminal:false}).on('line',line=>{let c;try{c=JSON.parse(line);}catch{return;}switch(c.type){
 case 'get_state':response(c,{sessionId:`fixture-${process.pid}`,sessionFile:file,thinkingLevel:'off',isStreaming:running,isCompacting:false,steeringMode:'all',followUpMode:'all',autoCompactionEnabled:true,messageCount:messages.length,pendingMessageCount:0});break;
 case 'get_messages':response(c,{messages});break;case 'get_entries':response(c,{entries:readFileSync(file,'utf8').trim().split('\n').slice(1).map(JSON.parse)});break;case 'get_commands':response(c,{commands:[]});break;
 case 'get_session_stats':response(c,{pid:process.pid,toolExecutions:executions,prompts:[...prompts]});break;
 case 'prompt':prompts.push(c.message);entry({role:'user',content:c.message,timestamp:Date.now()});running=true;executions++;current=assistant('earlier UTF8 界👋 partial');emit({type:'agent_start'});emit({type:'message_start',message:{...current,content:[]}});emit({type:'message_update',assistantMessageEvent:{type:'text_start',contentIndex:0}});emit({type:'message_update',assistantMessageEvent:{type:'text_delta',contentIndex:0,delta:'earlier UTF8 界👋 partial'}});emit({type:'tool_execution_start',toolCallId:'gate',toolName:'view_test_gate',args:{}});emit({type:'tool_execution_update',toolCallId:'gate',toolName:'view_test_gate',args:{},partialResult:{content:[{type:'text',text:'first tool output'}]}});if(c.message==='question')emit({type:'extension_ui_request',id:'pending-request',method:'input',title:'answer'});response(c);break;
 case 'extension_ui_response':if(c.id==='pending-request')settle();break;
 case 'set_session_name':if(c.name==='release-gate')settle();response(c);break;
 case 'clear_queue':response(c,{steering:[],followUp:[]});break;
 case 'abort':running=false;response(c);emit({type:'agent_settled'});break;
 default:response(c);
}});
process.on('SIGTERM',()=>{emit({type:'agent_settled'});process.exit(0);});
